import 'package:flutter/material.dart';
import '../../core/api_client.dart';
import '../../core/theme.dart';
import 'session_controller.dart';
class AddUserScreen extends StatefulWidget{const AddUserScreen({super.key,required this.session});final SessionController session;@override State<AddUserScreen> createState()=>_AddUserScreenState();}
class _AddUserScreenState extends State<AddUserScreen>{final name=TextEditingController(),phone=TextEditingController(),password=TextEditingController();String role='employee';bool saving=false;Future<void> save()async{setState(()=>saving=true);try{await widget.session.createUser(name:name.text.trim(),phone:phone.text.trim(),password:password.text,role:role);if(mounted)Navigator.pop(context,true);}on ApiException catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(e.message)));}finally{if(mounted)setState(()=>saving=false);}}@override void dispose(){name.dispose();phone.dispose();password.dispose();super.dispose();}@override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('Add user')),body:ListView(padding:const EdgeInsets.all(20),children:[TextField(controller:name,decoration:const InputDecoration(labelText:'Name')),TextField(controller:phone,keyboardType:TextInputType.phone,decoration:const InputDecoration(labelText:'Phone')),TextField(controller:password,obscureText:true,decoration:const InputDecoration(labelText:'Password (12+ characters)')),const SizedBox(height:14),DropdownButtonFormField(value:role,items:const [DropdownMenuItem(value:'hr_manager',child:Text('HR manager')),DropdownMenuItem(value:'supervisor',child:Text('Supervisor')),DropdownMenuItem(value:'employee',child:Text('Employee'))],onChanged:(v)=>setState(()=>role=v!),decoration:const InputDecoration(labelText:'Role')),const SizedBox(height:24),FilledButton(onPressed:saving?null:save,style:FilledButton.styleFrom(backgroundColor:HRMateTheme.blue,padding:const EdgeInsets.symmetric(vertical:16)),child:Text(saving?'Saving…':'Create user'))]));}
